body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.alerts {
  padding: 0 22px 22px;
  box-sizing: border-box;
}

.head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.head span {
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

h2 {
  margin: 3px 0 4px;
  font-size: 20px;
}

p {
  margin: 0;
  color: #667085;
  font-size: 13px;
}

.count {
  min-width: 42px;
  height: 34px;
  line-height: 34px;
  border-radius: 999px;
  background: #111827;
  color: white;
  text-align: center;
  font-weight: 900;
}

.alert-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 11px;
}

.alert {
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  padding: 13px;
}

.alert.critical {
  border-color: #fecaca;
  background: #fff1f2;
}

.alert.high {
  border-color: #fed7aa;
  background: #fff7ed;
}

.alert.medium {
  border-color: #bfdbfe;
  background: #eff6ff;
}

.top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.badge {
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  padding: 4px 7px;
  border-radius: 999px;
  border: 1px solid #d0d5dd;
  background: #fff;
}

.module {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.alert h3 {
  margin: 0 0 6px;
  font-size: 15px;
}

.alert p {
  font-size: 12px;
  line-height: 1.4;
}

.code {
  margin-top: 10px;
  color: #667085;
  font-size: 11px;
}

.empty {
  grid-column: 1/-1;
  border: 1px dashed #d0d5dd;
  border-radius: 8px;
  padding: 24px;
  color: #667085;
  text-align: center;
}

@media (max-width: 1100px) {
  .alert-list {
    grid-template-columns: 1fr;
  }
}

srcDoc.js:
function severityClass(value) {
  return String(value || "").toLowerCase();
}
function render(model = {}) {
  const alerts = model.alerts || [];
  document.getElementById("count").innerText = alerts.length;
  document.getElementById("alertList").innerHTML = alerts.length ? alerts.map(alert => `
      <div class="alert ${severityClass(alert.severity)}">
        <div class="top">
          <span class="badge">${alert.severity || "INFO"}</span>
          <span class="module">${alert.moduleName || ""}</span>
        </div>
        <h3>${alert.title || ""}</h3>
        <p>${alert.message || ""}</p>
        <div class="code">${alert.alertType || ""} / ${alert.entityCode || ""}</div>
      </div>
    `).join("") : `<div class="empty">No alerts right now.</div>`;
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

